def search_insert(nums, target):
    for index, value in enumerate(nums):
        if value >= target:
            return index + 1
    return len(nums)

def coin_change(coins, amount):
    if amount == 0:
        return 0
    ordered = sorted(coins, reverse=True)
    count = 0
    remaining = amount
    for coin in ordered:
        while remaining >= coin:
            remaining -= coin
            count += 1
    return count if remaining == 0 else -1
